import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';

describe('createInvoice', () => {
  test('creates a valid invoice with correct structure', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 2 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.customerId, 'C-001');
    assert.equal(result.value.issueDate, '2026-10-07');
    assert.equal(result.value.status, 'draft');
    assert.equal(result.value.lines.length, 1);

    const line = result.value.lines[0];
    assert.equal(line.sku, 'DES-HOUR');
    assert.equal(line.qty, 2);
    assert.equal(typeof line.name, 'string');
    assert.equal(typeof line.unitPrice, 'number');
    assert.equal(typeof line.vatRate, 'number');
  });

  test('includes catalogue data in lines', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert.equal(result.ok, true);
    const line = result.value.lines[0];
    assert.equal(line.name, 'Design work (hour)');
    assert.equal(line.unitPrice, 8500);
    assert.equal(line.vatRate, 21);
  });

  test('supports multiple lines', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 2 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines.length, 2);
  });

  test('rejects unknown customer', () => {
    const result = createInvoice({
      customerId: 'UNKNOWN',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
  });

  test('rejects malformed date', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '10/07/2026',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'DATE_INVALID');
  });

  test('rejects invalid date (Feb 30)', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'DATE_INVALID');
  });

  test('rejects invalid date (month 13)', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-13-01',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'DATE_INVALID');
  });

  test('rejects empty lines array', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NO_LINES');
  });

  test('rejects null lines', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: null,
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NO_LINES');
  });

  test('rejects non-integer quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1.5 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'QTY_INVALID');
  });

  test('rejects zero quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'QTY_INVALID');
  });

  test('rejects negative quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -1 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'QTY_INVALID');
  });

  test('rejects unknown SKU', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'NONEXISTENT', qty: 1 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'UNKNOWN_SKU');
  });

  test('stops validation at first SKU error', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'NONEXISTENT', qty: 1 },
      ],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'UNKNOWN_SKU');
  });

  test('does not mutate input', () => {
    const lines = [{ sku: 'DES-HOUR', qty: 1 }];
    const input = { customerId: 'C-001', issueDate: '2026-10-07', lines };

    createInvoice(input);

    assert.deepEqual(lines, [{ sku: 'DES-HOUR', qty: 1 }]);
  });

  test('accepts discount 0', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, 0);
  });

  test('accepts discount 50', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 50 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, 50);
  });

  test('accepts discount 100', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 100 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, 100);
  });

  test('accepts decimal discount (12.5)', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 12.5 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, 12.5);
  });

  test('rejects discount > 100', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 101 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  test('rejects negative discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: -1 }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  test('rejects non-number discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 'fifty' }],
    });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  test('applies gold tier discount when not provided', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, TIER_DISCOUNTS.gold);
  });

  test('applies standard tier discount when not provided', () => {
    const result = createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, TIER_DISCOUNTS.standard);
  });

  test('applies silver tier discount when not provided', () => {
    const result = createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, TIER_DISCOUNTS.silver);
  });

  test('explicit discountPercent of 0 overrides tier discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, 0);
  });

  test('explicit discount overrides tier discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 25 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, 25);
  });

  test('applies tier discounts to multiple lines with different overrides', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [
        { sku: 'DES-HOUR', qty: 1 },
        { sku: 'DEV-HOUR', qty: 1, discountPercent: 10 },
      ],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[0].discountPercent, TIER_DISCOUNTS.gold);
    assert.equal(result.value.lines[1].discountPercent, 10);
  });
});

describe('lineTotal', () => {
  test('calculates qty times unitPrice', () => {
    const line = { qty: 2, unitPrice: 8500 };
    assert.equal(lineTotal(line), 17000);
  });

  test('handles single unit', () => {
    const line = { qty: 1, unitPrice: 8500 };
    assert.equal(lineTotal(line), 8500);
  });

